package edu.ankara.audiometer.property;
import edu.ankara.audiometer.domain.algorithm.*;import edu.ankara.audiometer.domain.config.*;import edu.ankara.audiometer.domain.model.*;import net.jqwik.api.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class HughsonWestlakePropertiesTest { AudiometryConfig c=AudiometryConfig.defaults(); @Property void intensityAlwaysInsideRange(@ForAll @IntRange(min=0,max=80) int steps){ var s=TestState.initial(c); for(int i=0;i<steps;i++){ s=HughsonWestlakeEngine.presentTone(s); s=HughsonWestlakeEngine.applyResponseToLastPresentation(s,i%2==0?PatientResponse.HEARD:PatientResponse.NOT_HEARD); assertTrue(s.currentIntensity().value()>=c.minIntensity().value() && s.currentIntensity().value()<=c.maxIntensity().value()); } } @Property void heardNeverIncreases(@ForAll @IntRange(min=-10,max=120) int db){ var next=AudiometryFunctions.nextIntensityAfterResponse(new IntensityDbHL(db),PatientResponse.HEARD,c.algorithm(),c); assertTrue(next.value()<=db); } @Property void noResponseNeverDecreases(@ForAll @IntRange(min=-10,max=120) int db){ var next=AudiometryFunctions.nextIntensityAfterResponse(new IntensityDbHL(db),PatientResponse.NOT_HEARD,c.algorithm(),c); assertTrue(next.value()>=db); } @Property void thresholdBelongsToTestedEarFrequency(@ForAll @IntRange(min=10,max=60) int db){ var list=List.of(p(db,1),p(db,2),p(db,3)); var d=ThresholdDetector.detectThreshold(list,c.algorithm()); d.threshold().ifPresent(t->assertEquals(db,t.value())); } TonePresentation p(int db,int order){return new TonePresentation(Ear.LEFT,new FrequencyHz(2000),new IntensityDbHL(db),order,Optional.of(PatientResponse.HEARD),PresentationDirection.ASCENDING,true);} }
